// The vertical scroll position, clamped to the content; a view, since revealing a module moves it. A non-finite offset throws std::invalid_argument.
template <typename Declaring>
struct InstrumentRackScrollOffsetCapability {
    PropertyView<double, InstrumentRackScrollOffsetCapability<Declaring>> scroll_offset;

    static void assign(InstrumentRackScrollOffsetCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.scroll_offset), std::move(incoming));
    }

    static double read(const InstrumentRackScrollOffsetCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        double current = control.read_view(capability.scroll_offset);
        return current;
    }
};

// Every InstrumentRack capability, in the order the declaring class takes them.
template <typename Declaring>
struct InstrumentRackCapabilities : public InstrumentRackModuleWidthCapability<Declaring>,
                                    public InstrumentRackModuleHeightCapability<Declaring>,
                                    public InstrumentRackRackGapCapability<Declaring>,
                                    public InstrumentRackScrollOffsetCapability<Declaring> {};

